$_MODULE['<{retractationcommande}prestashop>demande_e1a266b5d2d6ad5263f80d3a3cb670b3'] = 'Uma vez que a sua encomenda ainda não foi expedida, não será necessária qualquer devolução de produto. Após a verificação do seu pedido pelo nosso serviço de apoio ao cliente, a expedição será anulada e a totalidade das quantias pagas ser-lhe-á reembolsada no prazo máximo de 14 dias após o seu pedido, através do mesmo meio de pagamento (art. L221-24).';
